<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="csrf-token" content="{{ csrf_token() }}"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#173e32"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="Everbranch Studio"><meta name="apple-mobile-web-app-status-bar-style" content="default"><meta name="referrer" content="no-referrer"><title>Everbranch Studio</title><meta name="description" content="Your voice. Your words. Your next chapter. A personal book studio for iPhone and iPad."><link rel="manifest" href="/studio/manifest.json"><link rel="apple-touch-icon" href="/studio/icon-192.png"><link rel="icon" href="/studio/icon.svg"><link rel="stylesheet" href="/studio/vendor/quill.snow.css"><link rel="stylesheet" href="/studio/studio.css"></head><body>
<header class="topbar"><a class="brand" id="brand-home" href="/studio/"><img src="/studio/icon.svg" alt="" width="38" height="38"><span>everbranch <b>studio</b></span></a><button id="settings" class="quiet">Book &amp; devices <span aria-hidden="true">↗</span></button></header>
<section class="studio-hero"><img src="/studio/renfrow/books.webp" alt="Original illustrative book photography"><div><h1>William’s Studio</h1><p>RENFROW LIBRARY · ILLUSTRATIVE PRIVATE DEMO</p></div></section>
<main class="shell"><nav class="studio-sidebar" aria-label="Studio navigation"><button id="nav-home" class="sidebar-home">⌂ Home <small>Choose a book</small></button><h2>Your books</h2><div id="sidebar-books"></div><h2 id="sidebar-chapter-title">Foundations</h2><button id="nav-new" class="secondary">＋ Add a Foundation</button><div id="sidebar-chapters"></div></nav><div class="main-content"><aside id="library" class="library"><div class="library-navigation"><button id="library-back" class="secondary" hidden>← Books</button><span id="library-count"></span></div><div class="eyebrow">YOUR BOOKSHELF</div><h1 id="book-name">Level Foundations</h1><p id="connection" class="connection">Local studio · no sign-in needed</p><div id="book-covers" class="book-covers"></div><button id="new" class="primary full">＋ Add a Foundation</button><label class="search-label"><span class="sr-only">Search chapters</span><input id="search" type="search" placeholder="Find a chapter…"></label><div id="chapter-list" class="chapters" aria-label="Chapters"></div><div class="library-foot"><span class="small-leaf">⌁</span><p>Your words, at your pace.<br><small>Made for phone &amp; tablet.</small></p><button id="install" class="quiet">Install app</button></div></aside>
<section id="workspace" class="workspace" hidden><div class="editor-navigation"><button id="editor-back" class="secondary">← Back</button><button id="save-exit" class="primary">Save &amp; exit</button><button id="discard-edits" class="discard-button">Discard edits</button><button id="editor-home" class="secondary">⌂ Home</button><span id="editor-publication" class="publication-badge"></span></div><div class="workspace-heading"><div><p class="eyebrow">A LITTLE SPACE TO CREATE</p><h2>Your next chapter starts here.</h2></div><span id="save-state" class="save-state" role="status">Ready</span></div>
<div id="empty" class="empty"><div class="empty-mark">⌁</div><h3>Something worth saying.</h3><p>Speak an idea, record your voice, or read a chapter aloud. We’ll keep your words here.</p><button id="first" class="primary">＋ Start a Foundation</button><p class="tiny">Connect your book once to open its chapters on both devices.</p></div>
<div id="editor" hidden><div class="paper"><img id="chapter-photo" class="chapter-photo" alt="Chapter picture" hidden><section id="publication-panel" class="publication-panel"><div><span id="publication-status" class="publication-badge"></span><p id="publication-explanation"></p></div><div class="publication-actions"><button id="review-publish" class="primary">Review &amp; publish</button><button id="move-draft" class="secondary" hidden>Move to draft</button><a id="published-link" target="_blank" rel="noopener" hidden>View on website ↗</a></div></section><div class="paper-top"><span id="chapter-label" class="eyebrow">FOUNDATION DRAFT</span><span id="word-count">0 words</span></div><label class="sr-only" for="title">Chapter title</label><textarea id="title" class="title" rows="1" placeholder="Give this chapter a title" maxlength="240"></textarea><div class="mode-bar"><button id="dictate">◉ Speak to text</button><button id="read">▷ Read &amp; follow</button><button id="listen">♫ Listen to text</button></div><label class="sr-only" for="body">Chapter text</label><div id="quill-toolbar"><span class="ql-formats"><button id="undo" type="button" aria-label="Undo">Undo</button><button id="redo" type="button" aria-label="Redo">Redo</button></span><span class="ql-formats"><select class="ql-header"><option value="1"></option><option value="2"></option><option selected></option></select></span><span class="ql-formats"><button class="ql-bold"></button><button class="ql-italic"></button><button class="ql-underline"></button><button class="ql-strike"></button></span><span class="ql-formats"><button class="ql-list" value="ordered"></button><button class="ql-list" value="bullet"></button><button class="ql-blockquote"></button></span><span class="ql-formats"><select class="ql-align"></select><button class="ql-link"></button><button class="ql-clean"></button></span></div><div id="rich-body"></div><textarea hidden id="body" placeholder="What would you like to say?&#10;&#10;Write here, or tap Speak to text. On iPhone and iPad you can also use the microphone on your keyboard." spellcheck></textarea><div class="paper-bottom"><span>Saved on this device as you write</span><button id="text-export" class="quiet">Export text ↗</button></div></div>
<div class="audio-card"><div class="audio-heading"><div><p class="eyebrow">IN YOUR OWN VOICE</p><h3>Your saved recordings.</h3></div><span id="timer">00:00</span></div><p class="audio-tip">Every take is kept. “Make live” chooses the recording heard on the website. Keep the app open while recording.</p><div class="audio-actions"><button id="record" class="record"><span class="record-dot"></span><span class="record-label">Record new audio</span></button><button id="stop" class="secondary" hidden>■ Finish recording</button><label class="secondary file-button">↑ Import audio<input id="audio-file" type="file" accept="audio/*,.m4a,.mp3,.wav,.webm,.ogg"></label></div><div id="audio-takes" class="audio-takes"></div><audio id="player" controls playsinline hidden></audio><div id="audio-tools" class="audio-tools" hidden><button id="transcribe" class="secondary">Audio → transcript</button><button id="cancel-transcription" class="secondary" hidden>Cancel transcription</button><button id="audio-export" class="quiet">Save audio ↗</button></div><p id="audio-message" class="tiny">Recordings stay private in your book’s studio.</p></div>
<div class="bottom-actions"><button id="sync" class="primary">Sync book</button><button id="website" class="secondary">Sync changes with website</button><button id="history" class="secondary">Version history</button><button id="duplicate" class="quiet">Save as new chapter</button></div></div>
<footer class="workspace-footer">EVERBRANCH STUDIO <span>A place for your voice to take root.</span></footer></section></div></main>
<dialog id="book-dialog"><form id="login-form"><button type="button" class="close" data-close="book-dialog" aria-label="Close">×</button><p class="eyebrow">ONE BOOK. ALL YOUR DEVICES.</p><h2>Bring your book along.</h2><p>Sign in once on each device. This app remembers your book for up to a year. Local writing and recording work without signing in.</p><div id="saved-books"></div><label>Book login<input name="book" id="login-book" value="level-foundations" autocomplete="username" required autocapitalize="none" spellcheck="false"></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="tiny">For Level Foundations, use its existing website administrator password. Other books have their own login.</p><button class="primary full" type="submit">Connect this book</button><p id="login-error" role="status"></p></form><div class="dialog-extra"><button id="local-mode" class="quiet">Use local studio</button><button id="create-book" class="quiet">Create another book</button><button id="import-local" class="quiet" hidden>Copy local drafts into this book</button><button id="logout" class="quiet" hidden>Disconnect this device</button></div></dialog>
<dialog id="create-dialog"><form id="create-form"><button type="button" class="close" data-close="create-dialog" aria-label="Close">×</button><p class="eyebrow">A NEW BOOK STUDIO</p><h2>Give each book its own home.</h2><p>Each book has a separate login, private chapters and recordings.</p><label>Book name<input name="name" required maxlength="160"></label><label>Book login<input name="book" required pattern="[a-z0-9-]+" autocapitalize="none" placeholder="my-next-book"></label><label>Book password<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><label>Site administrator password<input name="adminPassword" type="password" required autocomplete="off"></label><button class="primary full">Create book</button><p id="create-error" role="status"></p></form></dialog>
<dialog id="install-dialog"><button class="close" data-close="install-dialog" aria-label="Close">×</button><p class="eyebrow">ON YOUR HOME SCREEN</p><h2>Your studio, one tap away.</h2><ol><li>Open this Studio link in Chrome on the Galaxy Tab.</li><li>Open the Chrome menu, then <strong>Add to home screen → Install</strong>.</li><li>Name it <strong>Everbranch Studio</strong> and tap <strong>Add</strong>.</li><li>Open the installed app and connect your book once.</li></ol><p>Repeat on the iPad with the same book login. Open the app online once before using it offline.</p><p class="tiny">Live dictation and speech following need browser speech recognition. If unavailable in the installed app, use Chrome or the keyboard microphone. On-device audio transcription downloads a speech model on first use. Use Wi-Fi and a take under 10 minutes; longer recordings can be saved and exported.</p></dialog>
<section id="reader" class="reader" hidden><header><button id="reader-close" class="secondary">← Back to writing</button><span id="follow-state">Ready to read</span><button id="font-size" class="secondary" aria-label="Change reading text size">A↕</button></header><div class="reader-title" id="reader-title"></div><div id="reading-scroll" class="reading-scroll"><div id="reading-text"></div></div><footer><button id="reader-record" class="record">◉ Read &amp; record</button><button id="follow" class="secondary">Start voice following</button><button id="resume" class="primary" hidden>Resume following</button><button id="reader-listen" class="secondary">♫ Listen</button></footer></section>
<dialog id="publication-dialog" class="publication-dialog"><button class="close" id="publication-close" aria-label="Back to editor">×</button><p class="eyebrow">REVIEW → CONFIRM → PUBLISH</p><h2>Review before publishing</h2><p>Read your text, check the live audio, then confirm publication on levelfoundations.org.</p><div id="publication-preview"></div><div class="publication-review-actions"><button id="confirm-publication" class="primary">Publish to website</button><button id="publication-back" class="secondary">Back to editor</button></div><p id="publication-error" role="status"></p><p class="tiny">The published work uses the selected LIVE recording. Other saved takes stay private. Website book-access rules still apply.</p></dialog><dialog id="history-dialog"><button class="close" data-close="history-dialog" aria-label="Close">×</button><h2>Earlier saved copies</h2><p>Autosaved text versions. Restoring keeps the current copy and leaves live audio unchanged.</p><div id="history-list"></div><div id="version-preview" hidden></div></dialog><div id="toast" class="toast" role="status" aria-live="polite" hidden></div><script src="/studio/vendor/quill.js"></script><script type="module" src="/studio/studio.mjs"></script></body></html>
